const items = $input.all();

const numerosTexto = {
  "una": 1,
  "un": 1,
  "uno": 1,
  "dos": 2,
  "tres": 3,
  "cuatro": 4,
  "cinco": 5,
  "seis": 6,
  "siete": 7,
  "ocho": 8,
  "nueve": 9,
  "diez": 10
};

function convertirNumero(valor) {
  if (!valor) return null;

  const limpio = valor.toString().toLowerCase().trim();

  if (!isNaN(Number(limpio))) return Number(limpio);

  return numerosTexto[limpio] || null;
}

function extraerCodigoHabitacion(texto) {
  const textoUpper = String(texto || "").toUpperCase();

  // Detecta códigos como:
  // D-007, D007, SU-005, SU005, T-010, S-001, F-003
  const match = textoUpper.match(/\b(SU|D|T|S|F)\s*-?\s*(\d{1,3})\b/);

  if (!match) {
    return null;
  }

  const prefijo = match[1];
  const numero = match[2].padStart(3, "0");

  return `${prefijo}-${numero}`;
}

function inferirTipoPorCodigo(codigo) {
  if (!codigo) return null;

  const prefijo = codigo.split("-")[0];

  const mapa = {
    S: "sencilla",
    D: "doble",
    T: "triple",
    SU: "suite",
    F: "familiar"
  };

  return mapa[prefijo] || null;
}

function convertirTipoVisible(tipoDb) {
  const mapa = {
    sencilla: "habitación sencilla",
    doble: "habitación doble",
    triple: "habitación triple",
    familiar: "habitación familiar",
    suite: "suite"
  };

  return mapa[tipoDb] || null;
}

return items.map((item) => {
  const preguntaOriginal = item.json.pregunta_usuario || item.json.pregunta_original || "";
  const pregunta = item.json.pregunta_normalizada || preguntaOriginal.toLowerCase();

  const codigoHabitacionSolicitado = extraerCodigoHabitacion(
    pregunta || preguntaOriginal
  );

  const tipoInferidoPorCodigo = inferirTipoPorCodigo(codigoHabitacionSolicitado);

  let tipoHabitacion = null;
  let tipoHabitacionDb = null;

  if (pregunta.includes("sencilla")) {
    tipoHabitacion = "habitación sencilla";
    tipoHabitacionDb = "sencilla";
  } else if (pregunta.includes("doble")) {
    tipoHabitacion = "habitación doble";
    tipoHabitacionDb = "doble";
  } else if (pregunta.includes("triple")) {
    tipoHabitacion = "habitación triple";
    tipoHabitacionDb = "triple";
  } else if (pregunta.includes("familiar")) {
    tipoHabitacion = "habitación familiar";
    tipoHabitacionDb = "familiar";
  } else if (pregunta.includes("suite")) {
    tipoHabitacion = "suite";
    tipoHabitacionDb = "suite";
  }

  // Si el usuario no dijo "doble", "suite", etc.,
  // pero sí dijo un código como D-007, inferimos el tipo desde el código.
  if (!tipoHabitacionDb && tipoInferidoPorCodigo) {
    tipoHabitacionDb = tipoInferidoPorCodigo;
    tipoHabitacion = convertirTipoVisible(tipoInferidoPorCodigo);
  }

  const matchNoches = pregunta.match(/(\d+|una|un|uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\s+(noche|noches|dia|dias)/);
  const numeroNoches = matchNoches ? convertirNumero(matchNoches[1]) : null;

  const matchPersonas = pregunta.match(/para\s+(\d+|una|un|uno|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez)\s+(persona|personas|huesped|huespedes|adulto|adultos)/);
  const numeroPersonas = matchPersonas ? convertirNumero(matchPersonas[1]) : null;

  const matchFechaISO = pregunta.match(/\b(20\d{2}-\d{2}-\d{2})\b/);
  const matchFechaLatam = pregunta.match(/\b(\d{1,2}\/\d{1,2}\/20\d{2})\b/);

  let fechaEntrada = null;

  if (matchFechaISO) fechaEntrada = matchFechaISO[1];
  else if (matchFechaLatam) fechaEntrada = matchFechaLatam[1];
  else if (pregunta.includes("manana")) fechaEntrada = "mañana";
  else if (pregunta.includes("mañana")) fechaEntrada = "mañana";
  else if (pregunta.includes("hoy")) fechaEntrada = "hoy";

  const datosFaltantes = [];

  // Antes exigíamos siempre tipo de habitación.
  // Ahora aceptamos tipo de habitación O código de habitación.
  if (!tipoHabitacionDb && !codigoHabitacionSolicitado) {
    datosFaltantes.push("tipo de habitación o código de habitación");
  }

  if (!numeroNoches) datosFaltantes.push("número de noches");
  if (!numeroPersonas) datosFaltantes.push("número de personas");
  if (!fechaEntrada) datosFaltantes.push("fecha de entrada");

  const reservaCompleta = datosFaltantes.length === 0;

  return {
    json: {
      ...item.json,

      tipo_habitacion: tipoHabitacion,
      tipo_habitacion_db: tipoHabitacionDb,

      codigo_habitacion_solicitado: codigoHabitacionSolicitado,
      tipo_habitacion_inferida_codigo: tipoInferidoPorCodigo,

      numero_noches: numeroNoches,
      numero_personas: numeroPersonas,
      fecha_entrada: fechaEntrada,

      datos_faltantes: datosFaltantes,
      reserva_completa: reservaCompleta,
      estado_extraccion_reserva: reservaCompleta ? "datos_completos" : "faltan_datos"
    }
  };
});

